import boto3

def extract_receipt_info(receipt_path: str) -> dict:
    with open(receipt_path, 'rb') as f:
        image_bytes = f.read()
    client = boto3.client('textract')
    response = client.analyze_expense(Document={'Bytes': image_bytes})
    expense_doc = response['ExpenseDocuments'][0]
    summary_fields = expense_doc['SummaryFields']
    field_map = {field['Type']['Text']: field for field in summary_fields}
    merchant = ''
    for field in summary_fields:
        if field['Type']['Text'] == 'SIGNATURE':
            merchant = field['Value']['Text']
            break
    tax = 0.0
    if 'TAX_TOTAL' in field_map:
        tax_str = field_map['TAX_TOTAL']['Value']['Text'].replace('$', '').replace(',', '').strip()
        tax = float(tax_str) if tax_str else 0.0
    total = 0.0
    for total_type in ['INVOICE_TOTAL', 'TOTAL']:
        if total_type in field_map:
            total_str = field_map[total_type]['Value']['Text'].replace('$', '').replace(',', '').strip()
            total = float(total_str) if total_str else 0.0
            break
    items = []
    for group in expense_doc.get('LineItemGroups', []):
        for item in group.get('LineItems', []):
            name = item.get('Description', {}).get('Text', '')
            price_str = item.get('Price', {}).get('Value', {}).get('Text', '0')
            price = float(price_str.replace('$', '').replace(',', '').strip()) if price_str else 0.0
            if name:
                items.append({'name': name, 'price': price})
    return {
        'merchant': merchant,
        'tax': tax,
        'total': total,
        'items': items
    }
